export const bookTopics = bookData.map(c => c.topic);

/** Find a site by name — fuzzy match (handles typos, partial names, alternate spellings) */
export function findSiteByName(
  name: string,
  threshold = 75
): (BookSite & { topic: string; part: string; matchScore: number }) | undefined {
  const q = name.toLowerCase().trim();

  let bestMatch: (BookSite & { topic: string; part: string; matchScore: number }) | undefined;
  let bestScore = 0;

  for (const ch of bookData) {
    for (const s of ch.sites) {
      const sName = s.name.toLowerCase().trim();

      // Exact match — return immediately
      if (sName === q) return { ...s, topic: ch.topic, part: ch.part, matchScore: 100 };

      // Score 1: one contains the other
      let score = 0;
      if (sName.includes(q) || q.includes(sName)) {
        score = 90;
      } else {
        // Score 2: token overlap (handles word-order differences)
        const qTokens = new Set(q.split(/\s+/));
        const sTokens = new Set(sName.split(/\s+/));
        const intersection = [...qTokens].filter(t => sTokens.has(t)).length;
        const union = new Set([...qTokens, ...sTokens]).size;
        const jaccard = intersection / union;

        // Score 3: character-level similarity (Dice coefficient)
        const bigrams = (str: string) => {
          const b = new Set<string>();
          for (let i = 0; i < str.length - 1; i++) b.add(str.slice(i, i + 2));
          return b;
        };
        const qBi = bigrams(q);
        const sBi = bigrams(sName);
        const commonBi = [...qBi].filter(b => sBi.has(b)).length;
        const dice = (2 * commonBi) / (qBi.size + sBi.size || 1);

        score = Math.round(Math.max(jaccard, dice) * 100);
      }

      if (score > bestScore) {
        bestScore = score;
        bestMatch = { ...s, topic: ch.topic, part: ch.part, matchScore: score };
      }
    }
  }

  return bestScore >= threshold ? bestMatch : undefined;
}

/** Get top N fuzzy matches with scores — useful for showing "did you mean?" */
export function fuzzySearchSites(
  name: string,
  topN = 3
): (BookSite & { topic: string; part: string; matchScore: number })[] {
  const q = name.toLowerCase().trim();
  const results: (BookSite & { topic: string; part: string; matchScore: number })[] = [];

  for (const ch of bookData) {
    for (const s of ch.sites) {
      const sName = s.name.toLowerCase().trim();
      let score = 0;

      if (sName === q) score = 100;
      else if (sName.includes(q) || q.includes(sName)) score = 90;
      else {
        const qTokens = new Set(q.split(/\s+/));
        const sTokens = new Set(sName.split(/\s+/));
        const intersection = [...qTokens].filter(t => sTokens.has(t)).length;
        const union = new Set([...qTokens, ...sTokens]).size;
        const bigrams = (str: string) => {
          const b = new Set<string>();
          for (let i = 0; i < str.length - 1; i++) b.add(str.slice(i, i + 2));
          return b;
        };
        const qBi = bigrams(q);
        const sBi = bigrams(sName);
        const commonBi = [...qBi].filter(b => sBi.has(b)).length;
        const dice = (2 * commonBi) / (qBi.size + sBi.size || 1);
        const jaccard = intersection / union;
        score = Math.round(Math.max(jaccard, dice) * 100);
      }

      if (score > 0) results.push({ ...s, topic: ch.topic, part: ch.part, matchScore: score });
    }
  }

  return results.sort((a, b) => b.matchScore - a.matchScore).slice(0, topN);
}
